#!/bin/bash
# GPU box, Llama-3.1-8B: cache activations of the sampled ELEPHANT and Are You Sure responses in this repo
# (generated by judging/run_generate_openrouter.sh) and upload them to the Hub. Generates nothing; a rerun computes
# only missing (row, position) pairs.
# Needs: this branch with `git lfs pull` done, uv sync done, HF_TOKEN in .env (meta-llama + SycoScope),
# and CACHE_BATCH_SIZE set for the GPU.
set -euo pipefail
cd "$(dirname "$0")/.."
set -a; . ./.env; set +a
: "${CACHE_BATCH_SIZE:?set CACHE_BATCH_SIZE}"
MODEL=meta-llama/Llama-3.1-8B-Instruct
DECODING=Llama-3.1-8B-Instruct/t0.6_p0.9
GEN=generations/$DECODING/responses
AYS_MC=$GEN/are_you_sure_aqua_mc_math_mc_cot_mmlu_mc_cot_truthful_qa_mc_s0_responses.jsonl
AYS_FF=$GEN/are_you_sure_trivia_qa_truthful_qa_s0_responses.jsonl
INPUTS="$(for E in AITA-YTA OEQ SS AITA-NTA-OG AITA-NTA-FLIP; do echo -n "$GEN/${E}_s0_responses.jsonl "; done)$AYS_MC $AYS_FF"
CACHE=activations/cache
POSITIONS="prompt_last prompt_mean response_mean response_first5 response_first10 response_frac10 response_frac25 response_frac50 response_frac75"
mkdir -p $CACHE

.venv/bin/python -m pytest tests/test_cache_activations.py tests/test_extraction.py -q
.venv/bin/python -m interp.check_cache_parity --model $MODEL --input $GEN/SS_s0_responses.jsonl --n-rows 64 \
  --max-length 8192 2>&1 | tee activations/parity_ss_t0.6_p0.9.log
.venv/bin/python -m interp.check_cache_parity --model $MODEL --input $AYS_MC --n-rows 64 --max-length 8192 \
  2>&1 | tee activations/parity_ays_mc_t0.6_p0.9.log
.venv/bin/python -m interp.cache_activations --model $MODEL --positions $POSITIONS --cache-dir $CACHE \
  --max-length 8192 --batch-size $CACHE_BATCH_SIZE --inputs $INPUTS 2>&1 | tee activations/cache_t0.6_p0.9.log
# upload only this decoding's folder, so other local cache folders never reach the Hub
.venv/bin/hf upload SycoScope/activation-cache $CACHE/$DECODING $DECODING --repo-type dataset --exclude "*.tmp" \
  --commit-message "Llama-3.1-8B ELEPHANT and Are You Sure activations, T 0.6 top-p 0.9 seed 0, $(git rev-parse --short HEAD)"
